def translate(dna, frame=0, stop_at_stop=False):
    p=[]
    for i in range(frame, len(dna)-2, 3):
        aa = CODON[dna[i:i+3]]
        if aa=="*":
            if stop_at_stop: return "".join(p)
            p.append("*")
