            if cds[i] in starts:
                for j in range(i,n):
                    if cds[j] in stops:
                        if j-i+1>=minaa:
                            orfs.append((f+3*i+1, f+3*(j+1), (j-i+1)*3, cds[i]))
                        break
        if orfs: print(f"{label} frame {f+1}:"); 
        for st,en,L,sc in orfs: print(f"   {st}-{en} ({L} nt, {L//3-1} aa) start={sc} stop={s[en-3:en]}")
